// Every entry names its source (repo, path, commit, license); README Credits lists the repos.
// corpus.test.ts enforces the shape rules and the license allowlist. Reformatting is limited
// to expanding tabs, dropping comment-only lines, trimming to an excerpt and, where the
// comment above the entry says so, wrapping one long line. Generated by a scratch script
// (fetch via `gh api`), then committed; regenerate by hand if a source moves.
import type { CorpusFile } from '../../lessons/types';

// TheAlgorithms/TypeScript/dynamic_programming/lcs.ts @ 19b4ced86c99 (MIT) — excerpt: whole file, blank lines at the ends trimmed
const lcs: CorpusFile = {
  name: 'lcs.ts',
  source: { repo: 'TheAlgorithms/TypeScript', path: 'dynamic_programming/lcs.ts', commit: '19b4ced86c99815f142d4a46a028f55487b8038a', license: 'MIT' },
  lines: [
    "export const longestCommonSubsequence = (",
    "  text1: string,",
    "  text2: string",
    "): string => {",
    "  const m = text1.length",
    "  const n = text2.length",
    "",
    "  const dp: number[][] = Array.from({ length: m + 1 }, () =>",
    "    Array(n + 1).fill(0)",
    "  )",
    "",
    "  for (let i = 1; i <= m; i++) {",
    "    for (let j = 1; j <= n; j++) {",
    "      if (text1[i - 1] === text2[j - 1]) {",
    "        dp[i][j] = dp[i - 1][j - 1] + 1",
    "      } else {",
    "        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])",
    "      }",
    "    }",
    "  }",
    "",
    "  let i = m",
    "  let j = n",
    "  const lcs: string[] = []",
    "  while (i > 0 && j > 0) {",
    "    if (text1[i - 1] === text2[j - 1]) {",
    "      lcs.unshift(text1[i - 1])",
    "      i--",
    "      j--",
    "    } else if (dp[i - 1][j] > dp[i][j - 1]) {",
    "      i--",
    "    } else {",
    "      j--",
    "    }",
    "  }",
    "",
    "  return lcs.join('')",
    "}",
  ],
};

// TheAlgorithms/TypeScript/sorts/quick_select.ts @ 19b4ced86c99 (MIT) — excerpt: whole file
const quickSelect: CorpusFile = {
  name: 'quick_select.ts',
  source: { repo: 'TheAlgorithms/TypeScript', path: 'sorts/quick_select.ts', commit: '19b4ced86c99815f142d4a46a028f55487b8038a', license: 'MIT' },
  lines: [
    "import { partition } from './quick_sort'",
    "",
    "export const QuickSelect = (",
    "  array: number[],",
    "  k: number,",
    "  left: number = 0,",
    "  right: number = array.length - 1",
    "): number => {",
    "  if (k < 0 || k >= array.length) {",
    "    throw new Error('k is out of bounds')",
    "  }",
    "  if (left === right) {",
    "    return array[left]",
    "  }",
    "",
    "  const pivotIndex = partition(array, left, right)",
    "",
    "  if (k === pivotIndex) {",
    "    return array[k]",
    "  } else if (k < pivotIndex) {",
    "    return QuickSelect(array, k, left, pivotIndex - 1)",
    "  } else {",
    "    return QuickSelect(array, k, pivotIndex + 1, right)",
    "  }",
    "}",
  ],
};

// TheAlgorithms/TypeScript/data_structures/stack/stack.ts @ 19b4ced86c99 (MIT) — excerpt: whole file
const stack: CorpusFile = {
  name: 'stack.ts',
  source: { repo: 'TheAlgorithms/TypeScript', path: 'data_structures/stack/stack.ts', commit: '19b4ced86c99815f142d4a46a028f55487b8038a', license: 'MIT' },
  lines: [
    "export class Stack<T> {",
    "  private stack: T[] = []",
    "  private limit: number",
    "",
    "  constructor(limit: number = Number.MAX_VALUE) {",
    "    this.limit = limit",
    "  }",
    "",
    "  push(value: T) {",
    "    if (this.length() + 1 > this.limit) {",
    "      throw new Error('Stack Overflow')",
    "    }",
    "",
    "    this.stack.push(value)",
    "  }",
    "",
    "  pop(): T {",
    "    if (this.length() !== 0) {",
    "      return this.stack.pop() as T",
    "    }",
    "",
    "    throw new Error('Stack Underflow')",
    "  }",
    "",
    "  length(): number {",
    "    return this.stack.length",
    "  }",
    "",
    "  isEmpty(): boolean {",
    "    return this.length() === 0",
    "  }",
    "",
    "  top(): T | null {",
    "    if (this.length() !== 0) {",
    "      return this.stack[this.length() - 1]",
    "    }",
    "",
    "    return null",
    "  }",
    "}",
  ],
};

// unjs/ufo/src/query.ts @ f06c800d0c59 (MIT) — excerpt: parseQuery only; its generic header wrapped onto three lines
const query: CorpusFile = {
  name: 'query.ts',
  source: { repo: 'unjs/ufo', path: 'src/query.ts', commit: 'f06c800d0c59f2a4a1b9ba65eb6cb61a84419be6', license: 'MIT' },
  lines: [
    "export function parseQuery<",
    "  T extends ParsedQuery = ParsedQuery,",
    ">(",
    "  parametersString = \"\",",
    "): T {",
    "  const object: ParsedQuery = Object.create(null);",
    "  if (parametersString[0] === \"?\") {",
    "    parametersString = parametersString.slice(1);",
    "  }",
    "  for (const parameter of parametersString.split(\"&\")) {",
    "    const s = parameter.match(/([^=]+)=?(.*)/) || [];",
    "    if (s.length < 2) {",
    "      continue;",
    "    }",
    "    const key = decodeQueryKey(s[1]);",
    "    if (key === \"__proto__\" || key === \"constructor\") {",
    "      continue;",
    "    }",
    "    const value = decodeQueryValue(s[2] || \"\");",
    "    if (object[key] === undefined) {",
    "      object[key] = value;",
    "    } else if (Array.isArray(object[key])) {",
    "      (object[key] as string[]).push(value);",
    "    } else {",
    "      object[key] = [object[key] as string, value];",
    "    }",
    "  }",
    "  return object as T;",
    "}",
  ],
};

