// TheAlgorithms/Go/strings/kmp/kmp.go @ 5ba447ec5ff3 (MIT) — excerpt: the Kmp function only, doc comments dropped
const kmp: CorpusFile = {
  name: 'kmp.go',
  source: { repo: 'TheAlgorithms/Go', path: 'strings/kmp/kmp.go', commit: '5ba447ec5ff3d1213de65b92e726ee74c5d5cc19', license: 'MIT' },
  lines: [
    "package kmp",
    "",
    "func Kmp(word, text string, patternTable []int) []int {",
    "  if len(word) > len(text) {",
    "    return nil",
    "  }",
    "",
    "  var (",
    "    i, j    int",
    "    matches []int",
    "  )",
    "  for i+j < len(text) {",
    "",
    "    if word[j] == text[i+j] {",
    "      j++",
    "      if j == len(word) {",
    "        matches = append(matches, i)",
    "",
    "        i = i + j",
    "        j = 0",
    "      }",
    "    } else {",
    "      i = i + j - patternTable[j]",
    "      if patternTable[j] > -1 {",
    "        j = patternTable[j]",
    "      } else {",
    "        j = 0",
    "      }",
    "    }",
    "  }",
    "  return matches",
    "}",
  ],
};

