// stevearc/oil.nvim/lua/oil/adapters/files/permissions.lua @ b73018b75aff (MIT) — excerpt: mode_to_octal_str and str_to_mode
const permissions: CorpusFile = {
  name: 'permissions.lua',
  source: { repo: 'stevearc/oil.nvim', path: 'lua/oil/adapters/files/permissions.lua', commit: 'b73018b75affd13fa38e2fc94ef753b465f770d7', license: 'MIT' },
  lines: [
    "M.mode_to_octal_str = function(mode)",
    "  local mask = 7",
    "  return tostring(bit.band(mask, bit.rshift(mode, 9)))",
    "    .. tostring(bit.band(mask, bit.rshift(mode, 6)))",
    "    .. tostring(bit.band(mask, bit.rshift(mode, 3)))",
    "    .. tostring(bit.band(mask, mode))",
    "end",
    "",
    "local function str_to_mode(str)",
    "  local r, w, x = unpack(vim.split(str, \"\", {}))",
    "  local mode = 0",
    "  if r == \"r\" then",
    "    mode = bit.bor(mode, 4)",
    "  elseif r ~= \"-\" then",
    "    return nil",
    "  end",
    "  if w == \"w\" then",
    "    mode = bit.bor(mode, 2)",
    "  elseif w ~= \"-\" then",
    "    return nil",
    "  end",
    "  if x == \"x\" or x == \"t\" or x == \"s\" then",
    "    mode = bit.bor(mode, 1)",
    "  elseif x ~= \"-\" and x ~= \"T\" and x ~= \"S\" then",
    "    return nil",
    "  end",
    "  return mode",
    "end",
  ],
};

